document.addEventListener('DOMContentLoaded', function() {
    var calendarEl = document.getElementById('calendar');
    var version = (new Date()).valueOf();
    var calendar = new FullCalendar.Calendar(calendarEl, {
        initialView: 'listWeek',
        events: {
            url: 'rc-calendar.ics?version=' + version,
            format: 'ics'
        },
        views: {
            timeGridWeek: {
                nowIndicator: true
            }
        },
        headerToolbar: {
            start: 'listWeek,dayGridMonth,timeGridWeek', // will normally be on the left. if RTL, will be on the right
            center: 'title',
            end: 'prev,today,next' // will normally be on the right. if RTL, will be on the left
        }
    });
    calendar.render();
});
